import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useForm } from 'react-hook-form';
import { Button, Input, Modal, Table, Pagination } from '../../components/ui';
import { Plus, Pencil, Trash2 } from 'lucide-react';
import toast from 'react-hot-toast';

/**
 * Generic CRUD page.
 * @param {string} queryKey
 * @param {object} api - { getAll, create, update, delete }
 * @param {Array} columns - table column definitions (without actions)
 * @param {Function} FormFields - component({ register, errors })
 * @param {string} entityName
 */
export default function CrudPage({ queryKey, api, columns, FormFields, entityName }) {
  const qc = useQueryClient();
  const [page, setPage] = useState(0);
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState(null);

  const { data, isLoading } = useQuery({
    queryKey: [queryKey, page],
    queryFn: () => api.getAll({ page, size: 20 }),
  });

  const rows = data?.data?.data?.content || data?.data?.data || [];
  const totalPages = data?.data?.data?.totalPages || 0;

  const { register, handleSubmit, reset, formState: { errors, isSubmitting } } = useForm();

  const createMutation = useMutation({
    mutationFn: api.create,
    onSuccess: () => { qc.invalidateQueries([queryKey]); toast.success(`${entityName} created`); closeModal(); },
    onError: (e) => toast.error(e.response?.data?.message || 'Failed'),
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, data }) => api.update(id, data),
    onSuccess: () => { qc.invalidateQueries([queryKey]); toast.success(`${entityName} updated`); closeModal(); },
    onError: (e) => toast.error(e.response?.data?.message || 'Failed'),
  });

  const deleteMutation = useMutation({
    mutationFn: api.delete,
    onSuccess: () => { qc.invalidateQueries([queryKey]); toast.success(`${entityName} deleted`); },
    onError: (e) => toast.error(e.response?.data?.message || 'Failed'),
  });

  const openCreate = () => { setEditing(null); reset({}); setModalOpen(true); };
  const openEdit = (row) => { setEditing(row); reset(row); setModalOpen(true); };
  const closeModal = () => { setModalOpen(false); setEditing(null); reset({}); };

  const onSubmit = (formData) => {
    if (editing) updateMutation.mutate({ id: editing.id, data: formData });
    else createMutation.mutate(formData);
  };

  const allColumns = [
    ...columns,
    {
      key: 'actions', label: 'Actions', render: (r) => (
        <div className="flex gap-2">
          <button onClick={() => openEdit(r)} className="p-1.5 rounded hover:bg-slate-100 text-slate-500"><Pencil size={14} /></button>
          <button
            onClick={() => { if (window.confirm(`Delete this ${entityName}?`)) deleteMutation.mutate(r.id); }}
            className="p-1.5 rounded hover:bg-red-50 text-red-400"
          ><Trash2 size={14} /></button>
        </div>
      )
    }
  ];

  return (
    <div className="space-y-4">
      <div className="flex justify-end">
        <Button onClick={openCreate}><Plus size={16} /> Add {entityName}</Button>
      </div>
      <Table columns={allColumns} data={rows} loading={isLoading} />
      <Pagination page={page} totalPages={totalPages} onPageChange={setPage} />

      <Modal open={modalOpen} onClose={closeModal} title={editing ? `Edit ${entityName}` : `Add ${entityName}`}>
        <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
          <FormFields register={register} errors={errors} />
          <div className="flex justify-end gap-3 pt-2">
            <Button type="button" variant="secondary" onClick={closeModal}>Cancel</Button>
            <Button type="submit" disabled={isSubmitting}>{editing ? 'Update' : 'Create'}</Button>
          </div>
        </form>
      </Modal>
    </div>
  );
}
